/* ==========================================================================
   Web Piano Application Stylesheet
   ========================================================================== */

:root {
  --bg-primary: #12141a;
  --bg-secondary: #1a1e28;
  --bg-panel: #202636;
  --text-main: #f0f4fc;
  --text-muted: #8e9bb4;
  --accent-color: #3b82f6;
  --accent-hover: #2563eb;
  --accent-glow: rgba(59, 130, 246, 0.4);
  --border-color: #2e384d;

  /* Piano Keys */
  --white-key-bg: #ffffff;
  --white-key-border: #cbd5e1;
  --white-key-active: #e2e8f0;
  --white-key-shadow: 0 6px 8px rgba(0, 0, 0, 0.25);
  --white-key-active-shadow: 0 2px 4px rgba(0, 0, 0, 0.2);

  --black-key-bg: linear-gradient(180deg, #1f242d 0%, #0d0f14 100%);
  --black-key-active: #2b3240;
  --black-key-shadow: 0 4px 6px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.15);

  --font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-primary);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  overflow-x: hidden;
}

/* App Wrapper */
.piano-app {
  width: 100%;
  max-width: 900px;
  min-height: 100vh;
  margin: 0 auto;
  padding: 24px 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}

/* Header Section */
.header {
  text-align: center;
  width: 100%;
}

.title {
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  background: linear-gradient(135deg, #ffffff 0%, #94a3b8 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 6px;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
  font-weight: 400;
}

/* Controls Panel */
.controls-panel {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  justify-content: center;
  align-items: center;
  background-color: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 14px;
  padding: 16px 24px;
  width: 100%;
  max-width: 760px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 140px;
  flex: 1;
}

.control-label {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.select-input {
  background-color: var(--bg-panel);
  color: var(--text-main);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 8px 12px;
  font-size: 0.9rem;
  outline: none;
  cursor: pointer;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.select-input:focus {
  border-color: var(--accent-color);
  box-shadow: 0 0 0 2px var(--accent-glow);
}

.slider-input {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  background: var(--bg-panel);
  border-radius: 4px;
  outline: none;
  cursor: pointer;
  margin: 10px 0;
}

.slider-input::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--accent-color);
  cursor: pointer;
  box-shadow: 0 0 6px rgba(0, 0, 0, 0.4);
  transition: transform 0.15s, background-color 0.15s;
}

.slider-input::-webkit-slider-thumb:hover {
  transform: scale(1.15);
  background: var(--accent-hover);
}

.slider-input::-moz-range-thumb {
  width: 18px;
  height: 18px;
  border: none;
  border-radius: 50%;
  background: var(--accent-color);
  cursor: pointer;
  box-shadow: 0 0 6px rgba(0, 0, 0, 0.4);
  transition: transform 0.15s, background-color 0.15s;
}

.slider-input::-moz-range-thumb:hover {
  transform: scale(1.15);
  background: var(--accent-hover);
}

/* Keyboard Container */
.keyboard-container {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px 0;
  overflow-x: auto;
  touch-action: manipulation;
}

/* Piano Keyboard Base */
.piano-keyboard {
  position: relative;
  display: flex;
  background-color: #0b0d11;
  padding: 14px 12px 16px 12px;
  border-radius: 12px;
  box-shadow: 
    0 16px 36px rgba(0, 0, 0, 0.6),
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    inset 0 -3px 0 #000000;
  border: 1px solid #1c222e;
}

/* Generic Key Styles */
.key {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  cursor: pointer;
  transition: transform 0.05s ease, background-color 0.08s ease, box-shadow 0.08s ease;
  user-select: none;
  touch-action: none;
}

/* White Keys */
.white-key {
  width: 60px;
  height: 240px;
  background: var(--white-key-bg);
  border: 1px solid var(--white-key-border);
  border-bottom-left-radius: 6px;
  border-bottom-right-radius: 6px;
  margin: 0 1px;
  z-index: 1;
  box-shadow: var(--white-key-shadow);
  color: #475569;
  padding-bottom: 12px;
}

.white-key:hover {
  background: #f8fafc;
}

.white-key.key-active {
  background: var(--white-key-active);
  transform: translateY(3px);
  box-shadow: var(--white-key-active-shadow);
  border-color: #94a3b8;
  color: #0f172a;
}

/* Black Keys */
.black-key {
  position: absolute;
  width: 36px;
  height: 148px;
  background: var(--black-key-bg);
  border-bottom-left-radius: 4px;
  border-bottom-right-radius: 4px;
  z-index: 2;
  box-shadow: var(--black-key-shadow);
  color: #94a3b8;
  padding-bottom: 10px;
}

.black-key:hover {
  background: linear-gradient(180deg, #2d3340 0%, #171b24 100%);
}

.black-key.key-active {
  background: var(--black-key-active);
  transform: translateY(2px) scale(0.98);
  box-shadow: 0 2px 3px rgba(0, 0, 0, 0.6), inset 0 0 8px rgba(59, 130, 246, 0.3);
  color: #f8fafc;
}

/* Key Labels & Shortcuts */
.key-label {
  font-size: 0.85rem;
  font-weight: 700;
  pointer-events: none;
  line-height: 1.2;
}

.black-key .key-label {
  font-size: 0.75rem;
}

.key-shortcut {
  font-size: 0.7rem;
  font-weight: 500;
  opacity: 0.7;
  pointer-events: none;
  margin-top: 2px;
  background: rgba(0, 0, 0, 0.06);
  padding: 1px 4px;
  border-radius: 3px;
}

.black-key .key-shortcut {
  background: rgba(255, 255, 255, 0.12);
  color: #cbd5e1;
}

/* Instruction Banner */
.instruction-banner {
  background: rgba(32, 38, 54, 0.75);
  backdrop-filter: blur(8px);
  border: 1px solid var(--border-color);
  border-radius: 10px;
  padding: 10px 18px;
  font-size: 0.85rem;
  color: var(--text-muted);
  text-align: center;
  max-width: 640px;
  line-height: 1.5;
}

/* Footer Information */
.footer-info {
  font-size: 0.8rem;
  color: #64748b;
  text-align: center;
  padding-bottom: 8px;
}

/* Responsive adjustments */
@media (max-width: 640px) {
  .title {
    font-size: 1.6rem;
  }

  .controls-panel {
    padding: 12px 16px;
    gap: 12px;
  }

  .control-group {
    min-width: 100%;
  }

  .piano-keyboard {
    padding: 10px 8px 12px 8px;
  }

  .white-key {
    width: 38px;
    height: 180px;
    padding-bottom: 8px;
  }

  .black-key {
    width: 24px;
    height: 112px;
    padding-bottom: 6px;
  }

  .key-label {
    font-size: 0.72rem;
  }

  .black-key .key-label {
    font-size: 0.65rem;
  }

  .key-shortcut {
    font-size: 0.6rem;
  }
}

export type WaveformType = 'sine' | 'triangle' | 'sawtooth' | 'square';

export interface PianoKey {
  note: string;
  noteNameJp: string;
  noteNameEn: string;
  freq: number;
  isBlack: boolean;
  keyBinding: string;
}

export interface SoundSettings {
  volume: number;
  waveform: WaveformType;
  noteDisplay: 'jp' | 'en' | 'none';
}

export interface ActiveVoice {
  oscillator: OscillatorNode;
  gainNode: GainNode;
  filterNode?: BiquadFilterNode;
}

import { PianoKey, WaveformType, ActiveVoice } from './types';

export const PIANO_KEYS: PianoKey[] = [
  { note: 'C4', noteNameJp: 'ド', noteNameEn: 'C4', freq: 261.63, isBlack: false, keyBinding: 'a' },
  { note: 'C#4', noteNameJp: 'ド#', noteNameEn: 'C#4', freq: 277.18, isBlack: true, keyBinding: 'w' },
  { note: 'D4', noteNameJp: 'レ', noteNameEn: 'D4', freq: 293.66, isBlack: false, keyBinding: 's' },
  { note: 'D#4', noteNameJp: 'レ#', noteNameEn: 'D#4', freq: 311.13, isBlack: true, keyBinding: 'e' },
  { note: 'E4', noteNameJp: 'ミ', noteNameEn: 'E4', freq: 329.63, isBlack: false, keyBinding: 'd' },
  { note: 'F4', noteNameJp: 'ファ', noteNameEn: 'F4', freq: 349.23, isBlack: false, keyBinding: 'f' },
  { note: 'F#4', noteNameJp: 'ファ#', noteNameEn: 'F#4', freq: 369.99, isBlack: true, keyBinding: 't' },
  { note: 'G4', noteNameJp: 'ソ', noteNameEn: 'G4', freq: 392.00, isBlack: false, keyBinding: 'g' },
  { note: 'G#4', noteNameJp: 'ソ#', noteNameEn: 'G#4', freq: 415.30, isBlack: true, keyBinding: 'y' },
  { note: 'A4', noteNameJp: 'ラ', noteNameEn: 'A4', freq: 440.00, isBlack: false, keyBinding: 'h' },
  { note: 'A#4', noteNameJp: 'ラ#', noteNameEn: 'A#4', freq: 466.16, isBlack: true, keyBinding: 'u' },
  { note: 'B4', noteNameJp: 'シ', noteNameEn: 'B4', freq: 493.88, isBlack: false, keyBinding: 'j' },
  { note: 'C5', noteNameJp: '高ド', noteNameEn: 'C5', freq: 523.25, isBlack: false, keyBinding: 'k' },
];

class AudioEngine {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private activeVoices: Map<string, ActiveVoice> = new Map();

  private getAudioContext(): AudioContext {
    if (!this.ctx) {
      const AudioCtxClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      this.ctx = new AudioCtxClass();

      const master = this.ctx.createGain();
      master.gain.setValueAtTime(0.7, this.ctx.currentTime);
      master.connect(this.ctx.destination);
      this.masterGain = master;
    }
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
    return this.ctx;
  }

  public setMasterVolume(volume: number): void {
    if (this.masterGain && this.ctx) {
      const clampedVol = Math.max(0, Math.min(1, volume));
      this.masterGain.gain.setValueAtTime(clampedVol, this.ctx.currentTime);
    }
  }

  public startNote(note: string, freq: number, waveform: WaveformType, volume: number): void {
    const ctx = this.getAudioContext();
    this.setMasterVolume(volume);

    // 既に同一ノートが発音中なら素早くリリース
    if (this.activeVoices.has(note)) {
      this.stopNote(note);
    }

    const now = ctx.currentTime;

    const osc = ctx.createOscillator();
    const voiceGain = ctx.createGain();
    const filter = ctx.createBiquadFilter();

    osc.type = waveform;
    osc.frequency.setValueAtTime(freq, now);

    // 音色に応じたフィルターとエンベロープ特性を設定
    let attackTime = 0.008;
    let decayTime = 0.35;
    let sustainLevel = 0.4;
    let cutoffFreq = Math.min(freq * 6, 12000);

    if (waveform === 'triangle') {
      // ピアノに近い丸みのある減衰
      attackTime = 0.005;
      decayTime = 0.45;
      sustainLevel = 0.3;
      cutoffFreq = Math.min(freq * 4, 8000);
    } else if (waveform === 'square') {
      // オルガン風（持続性重視）
      attackTime = 0.015;
      decayTime = 0.15;
      sustainLevel = 0.7;
      cutoffFreq = Math.min(freq * 5, 9000);
    } else if (waveform === 'sawtooth') {
      // ブライトなシンセ
      attackTime = 0.01;
      decayTime = 0.25;
      sustainLevel = 0.5;
      cutoffFreq = Math.min(freq * 5, 10000);
    } else {
      // sine: ピュアトーン
      attackTime = 0.012;
      decayTime = 0.3;
      sustainLevel = 0.5;
      cutoffFreq = 16000;
    }

    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(cutoffFreq, now);

    // ADSR (Attack -> Decay -> Sustain)
    voiceGain.gain.setValueAtTime(0.0001, now);
    voiceGain.gain.exponentialRampToValueAtTime(1.0, now + attackTime);
    voiceGain.gain.exponentialRampToValueAtTime(sustainLevel, now + attackTime + decayTime);

    osc.connect(filter);
    filter.connect(voiceGain);
    if (this.masterGain) {
      voiceGain.connect(this.masterGain);
    }

    osc.start(now);

    this.activeVoices.set(note, {
      oscillator: osc,
      gainNode: voiceGain,
      filterNode: filter,
    });
  }

  public stopNote(note: string): void {
    const voice = this.activeVoices.get(note);
    if (!voice || !this.ctx) return;

    const now = this.ctx.currentTime;
    const releaseTime = 0.18;

    voice.gainNode.gain.cancelScheduledValues(now);
    // 現在の音量から安全にフェードアウト
    voice.gainNode.gain.setValueAtTime(voice.gainNode.gain.value, now);
    voice.gainNode.gain.exponentialRampToValueAtTime(0.0001, now + releaseTime);

    voice.oscillator.stop(now + releaseTime + 0.02);

    setTimeout(() => {
      try {
        voice.oscillator.disconnect();
        voice.gainNode.disconnect();
        if (voice.filterNode) {
          voice.filterNode.disconnect();
        }
      } catch {
        // 切断済み例外は安全に無視
      }
    }, (releaseTime + 0.05) * 1000);

    this.activeVoices.delete(note);
  }

  public stopAllNotes(): void {
    const notes = Array.from(this.activeVoices.keys());
    notes.forEach((note) => this.stopNote(note));
  }
}

export const audioEngine = new AudioEngine();

import { useState, useEffect, useCallback, useRef } from 'react';
import { PIANO_KEYS, audioEngine } from './audioUtils';
import { SoundSettings, PianoKey } from './types';

interface KeyboardProps {
  settings: SoundSettings;
}

const Keyboard = ({
  settings = { volume: 0.7, waveform: 'triangle', noteDisplay: 'jp' },
}: KeyboardProps) => {
  const [activeNotes, setActiveNotes] = useState<Set<string>>(new Set());
  const activeNotesRef = useRef<Set<string>>(new Set());
  activeNotesRef.current = activeNotes;

  const containerRef = useRef<HTMLDivElement>(null);
  const whiteKeyRefs = useRef<Map<string, HTMLDivElement>>(new Map());
  const [blackKeyLefts, setBlackKeyLefts] = useState<Record<string, number>>({});

  // 音の再生開始
  const handleNoteStart = useCallback(
    (keyItem: PianoKey) => {
      if (activeNotesRef.current.has(keyItem.note)) return;

      audioEngine.startNote(
        keyItem.note,
        keyItem.freq,
        settings.waveform,
        settings.volume
      );

      setActiveNotes((prev) => {
        const next = new Set(prev);
        next.add(keyItem.note);
        return next;
      });
    },
    [settings.waveform, settings.volume]
  );

  // 音の停止
  const handleNoteStop = useCallback((note: string) => {
    audioEngine.stopNote(note);
    setActiveNotes((prev) => {
      if (!prev.has(note)) return prev;
      const next = new Set(prev);
      next.delete(note);
      return next;
    });
  }, []);

  // すべての音を安全に停止
  const handleStopAll = useCallback(() => {
    audioEngine.stopAllNotes();
    setActiveNotes(new Set());
  }, []);

  // 黒鍵の水平位置（left px）を白鍵の実際の位置から算出
  const updateBlackKeyPositions = useCallback(() => {
    const container = containerRef.current;
    if (!container) return;

    const containerRect = container.getBoundingClientRect();
    const newLefts: Record<string, number> = {};

    // 黒鍵と対応する基準白鍵（その左側の白鍵）のマッピング
    const blackKeyAnchorMap: Record<string, string> = {
      'C#4': 'C4',
      'D#4': 'D4',
      'F#4': 'F4',
      'G#4': 'G4',
      'A#4': 'A4',
    };

    // 画面幅による黒鍵の幅判定
    const isMobile = window.innerWidth <= 640;
    const blackKeyWidth = isMobile ? 24 : 36;

    Object.entries(blackKeyAnchorMap).forEach(([blackNote, anchorWhiteNote]) => {
      const whiteElement = whiteKeyRefs.current.get(anchorWhiteNote);
      if (whiteElement) {
        const whiteRect = whiteElement.getBoundingClientRect();
        // 白鍵の右端を中心に黒鍵をセンタリング
        const rightEdgeRelativeToContainer = whiteRect.right - containerRect.left;
        newLefts[blackNote] = Math.round(rightEdgeRelativeToContainer - blackKeyWidth / 2);
      }
    });

    setBlackKeyLefts(newLefts);
  }, []);

  // リサイズ検知と初期計算
  useEffect(() => {
    updateBlackKeyPositions();
    const handleResize = () => {
      updateBlackKeyPositions();
    };

    window.addEventListener('resize', handleResize);
    // 初回レンダリングのレイアウト確定時にも実行
    const timer = setTimeout(updateBlackKeyPositions, 50);

    return () => {
      window.removeEventListener('resize', handleResize);
      clearTimeout(timer);
    };
  }, [updateBlackKeyPositions]);

  // PCキーボードによる演奏イベント
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      // 入力フォーム操作中は演奏を無効化
      if (
        event.target instanceof HTMLInputElement ||
        event.target instanceof HTMLSelectElement ||
        event.target instanceof HTMLTextAreaElement
      ) {
        return;
      }

      if (event.repeat) return;

      const pressedKey = event.key.toLowerCase();
      const matchedKey = PIANO_KEYS.find((k) => k.keyBinding === pressedKey);

      if (matchedKey) {
        event.preventDefault();
        handleNoteStart(matchedKey);
      }
    };

    const handleKeyUp = (event: KeyboardEvent) => {
      const pressedKey = event.key.toLowerCase();
      const matchedKey = PIANO_KEYS.find((k) => k.keyBinding === pressedKey);

      if (matchedKey) {
        event.preventDefault();
        handleNoteStop(matchedKey.note);
      }
    };

    const handleWindowBlur = () => {
      handleStopAll();
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('blur', handleWindowBlur);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('blur', handleWindowBlur);
      audioEngine.stopAllNotes();
    };
  }, [handleNoteStart, handleNoteStop, handleStopAll]);

  // 音名表示用テキスト
  const getNoteDisplayText = (keyItem: PianoKey): string => {
    if (settings.noteDisplay === 'jp') {
      return keyItem.noteNameJp;
    }
    if (settings.noteDisplay === 'en') {
      return keyItem.noteNameEn;
    }
    return '';
  };

  const whiteKeys = PIANO_KEYS.filter((k) => !k.isBlack);
  const blackKeys = PIANO_KEYS.filter((k) => k.isBlack);

  return (
    <div className="keyboard-container">
      <div className="piano-keyboard" ref={containerRef}>
        {/* 白鍵群の描画 */}
        {whiteKeys.map((keyItem) => {
          const isActive = activeNotes.has(keyItem.note);
          const displayText = getNoteDisplayText(keyItem);

          return (
            <div
              key={keyItem.note}
              ref={(el) => {
                if (el) {
                  whiteKeyRefs.current.set(keyItem.note, el);
                } else {
                  whiteKeyRefs.current.delete(keyItem.note);
                }
              }}
              className={`key white-key ${isActive ? 'key-active' : ''}`}
              onPointerDown={(e) => {
                e.preventDefault();
                (e.currentTarget as HTMLElement).releasePointerCapture(e.pointerId);
                handleNoteStart(keyItem);
              }}
              onPointerUp={(e) => {
                e.preventDefault();
                handleNoteStop(keyItem.note);
              }}
              onPointerLeave={(e) => {
                e.preventDefault();
                handleNoteStop(keyItem.note);
              }}
              onPointerCancel={(e) => {
                e.preventDefault();
                handleNoteStop(keyItem.note);
              }}
              role="button"
              tabIndex={0}
              aria-label={`${keyItem.noteNameJp} (${keyItem.note})`}
            >
              {displayText && <span className="key-label">{displayText}</span>}
              <span className="key-shortcut">{keyItem.keyBinding.toUpperCase()}</span>
            </div>
          );
        })}

        {/* 黒鍵群の描画（絶対配置） */}
        {blackKeys.map((keyItem) => {
          const isActive = activeNotes.has(keyItem.note);
          const displayText = getNoteDisplayText(keyItem);
          const leftPos = blackKeyLefts[keyItem.note];

          const inlineStyle = leftPos !== undefined ? { left: `${leftPos}px` } : undefined;

          return (
            <div
              key={keyItem.note}
              style={inlineStyle}
              className={`key black-key ${isActive ? 'key-active' : ''}`}
              onPointerDown={(e) => {
                e.preventDefault();
                e.stopPropagation();
                (e.currentTarget as HTMLElement).releasePointerCapture(e.pointerId);
                handleNoteStart(keyItem);
              }}
              onPointerUp={(e) => {
                e.preventDefault();
                e.stopPropagation();
                handleNoteStop(keyItem.note);
              }}
              onPointerLeave={(e) => {
                e.preventDefault();
                e.stopPropagation();
                handleNoteStop(keyItem.note);
              }}
              onPointerCancel={(e) => {
                e.preventDefault();
                e.stopPropagation();
                handleNoteStop(keyItem.note);
              }}
              role="button"
              tabIndex={0}
              aria-label={`${keyItem.noteNameJp} (${keyItem.note})`}
            >
              {displayText && <span className="key-label">{displayText}</span>}
              <span className="key-shortcut">{keyItem.keyBinding.toUpperCase()}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default Keyboard;

import { useState, ChangeEvent } from 'react';
import Keyboard from './Keyboard';
import { SoundSettings, WaveformType } from './types';
import { audioEngine } from './audioUtils';

const App = () => {
  const [settings, setSettings] = useState<SoundSettings>({
    volume: 0.7,
    waveform: 'triangle',
    noteDisplay: 'jp',
  });

  const handleWaveformChange = (e: ChangeEvent<HTMLSelectElement>) => {
    const val = e.target.value as WaveformType;
    setSettings((prev) => ({ ...prev, waveform: val }));
  };

  const handleVolumeChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setSettings((prev) => ({ ...prev, volume: val }));
    audioEngine.setMasterVolume(val);
  };

  const handleNoteDisplayChange = (e: ChangeEvent<HTMLSelectElement>) => {
    const val = e.target.value as 'jp' | 'en' | 'none';
    setSettings((prev) => ({ ...prev, noteDisplay: val }));
  };

  return (
    <div className="piano-app">
      {/* ヘッダーエリア */}
      <header className="header">
        <h1 className="title">WEB PIANO</h1>
        <p className="subtitle">1オクターブ（ド〜高いド）対応リアルタイム音源ピアノ</p>
      </header>

      {/* サウンド＆表示コントロールパネル */}
      <section className="controls-panel" aria-label="ピアノ設定コントロール">
        <div className="control-group">
          <label htmlFor="waveform-select" className="control-label">
            音色（波形）
          </label>
          <select
            id="waveform-select"
            className="select-input"
            value={settings.waveform}
            onChange={handleWaveformChange}
          >
            <option value="triangle">ピアノ風（三角波）</option>
            <option value="sine">ピュアトーン（サイン波）</option>
            <option value="square">オルガン風（矩形波）</option>
            <option value="sawtooth">シンセ風（ノコギリ波）</option>
          </select>
        </div>

        <div className="control-group">
          <label htmlFor="volume-slider" className="control-label">
            音量 ({Math.round(settings.volume * 100)}%)
          </label>
          <input
            id="volume-slider"
            type="range"
            min="0"
            max="1"
            step="0.01"
            value={settings.volume}
            onChange={handleVolumeChange}
            className="slider-input"
            aria-label="マスター音量スライダー"
          />
        </div>

        <div className="control-group">
          <label htmlFor="display-select" className="control-label">
            音名ラベル表示
          </label>
          <select
            id="display-select"
            className="select-input"
            value={settings.noteDisplay}
            onChange={handleNoteDisplayChange}
          >
            <option value="jp">日本語 (ド レ ミ)</option>
            <option value="en">英語 (C4 D4 E4)</option>
            <option value="none">非表示</option>
          </select>
        </div>
      </section>

      {/* 鍵盤コンポーネント */}
      <Keyboard settings={settings} />

