      <div className="instruction-banner">
        <strong>【操作方法】</strong> 白鍵・黒鍵をクリックまたはタッチして演奏できます。
        <br />
        PCキーボード操作にも対応：白鍵［A, S, D, F, G, H, J, K］／ 黒鍵［W, E, T, Y, U］
      </div>

      {/* フッター情報 */}
      <footer className="footer-info">
        Web Audio API リアルタイムシンセシス音源 ・ ADSRエンベロープ制御対応
      </footer>
    </div>
  );
};

